namespace Wayel.Infrastructure.Persistence.Mongo.Seed;

internal static class KycDemoPlaceholderImages
{
    internal static byte[] ForSide(string side) =>
        side switch
        {
            "back" => Back,
            "selfie" => Selfie,
            _ => Front,
        };

    private static readonly byte[] Front = Convert.FromBase64String(
        "");

    private static readonly byte[] Back = Convert.FromBase64String(
        "");

    private static readonly byte[] Selfie = Convert.FromBase64String(
        "");

}
